/**
 * Initialize the inventory request for a Niagara/OBIX controller.
 *
 * Reads controller connection settings from global config:
 *   global.get('config', 'persistent') or global.get('config')
 *
 * Expected config fields (mocked or real):
 *   host    – controller IP or hostname
 *   scheme  – http/https (default: https)
 *   port    – optional port
 *   baseUrl – OBIX base path, e.g. "obix"
 */
var config = global.get('config', 'persistent') || global.get('config') || {};
var host = config.host;
var scheme = config.scheme;


msg.controllerIp = host;
msg.url = scheme + "://" + host + "/obix/config/System/";

return msg;

/**
 * Attach saved Niagara/OBIX session cookie (if any) to the request
 * when listing all systems.
 *
 * Cookie is stored in flow context as "niagaraCookie".
 */
var c = flow.get("niagaraCookie");
msg.headers = msg.headers || {};
if (c) {
    msg.headers["Cookie"] = c;
}
return msg;

/**
 * Extracts system folders from the OBIX /config/System/ response.
 *
 * Expects msg.payload to be the XML→JSON representation where
 *   payload.obj.ref contains references to system folders (VS3, AS01, ...).
 *
 * Output:
 *   msg.systems – array of system identifiers
 *   msg.payload – same array (for chaining)
 */
var root = msg.payload;
if (root && root.obj) root = root.obj;

var refs = root && root.ref ? root.ref : [];
if (!Array.isArray(refs)) refs = [refs];

var systems = [];

refs.forEach(function (r) {
    if (!r || !r.$) return;
    var a = r.$;
    if (!a.href) return;

    // Example href: "/obix/config/System/VS3/"
    if (a.href.endsWith("/")) {
        var name = a.href.replace(/\/$/, "");
        systems.push(name);
    }
});

msg.systems = systems;
msg.payload = systems;
return msg;

/**
 * For each discovered system, set systemName and build the
 * URL used to fetch the system folder details.
 */
var systemName = msg.payload; // e.g. "VS3" or a path fragment
msg.systemName = systemName;

var config = global.get('config', 'persistent') || global.get('config') || {};
var host = config.host;
var scheme = config.scheme;


msg.controllerIp = host;
msg.url = scheme + "://" + host + "/obix/config/System/" + systemName;

return msg;

/**
 * Attach the Niagara session cookie for system detail requests.
 */
var c = flow.get("niagaraCookie");
msg.headers = msg.headers || {};
if (c) {
    msg.headers["Cookie"] = c;
}
return msg;

/**
 * Build point metadata and inventory entries from a system folder response.
 *
 * Responsibilities:
 *  - Scan OBIX <ref> entries that represent points (obix:Point)
 *  - Infer system and component names from point name
 *  - Build a normalized /out/ URI and store it in `label`
 *  - Maintain a global obixGrossList structure keyed by IP and system
 *  - Produce a list of points (system + label) for subsequent GET /out/ calls
 *
 * Global context:
 *  - config.host, config.property, etc.
 *  - obixGrossList[ip].systems[systemName] – array of point objects
 */
var config = global.get('config', 'persistent') || global.get('config') || {};
var configHost = config.host || "localhost";
var configProperty = config.property || null;

var ip = msg.controllerIp || configHost;
var systemName = msg.systemName;

// Root from XML→JSON
var root = msg.payload;
if (root && root.obj) root = root.obj;

// List of ref = points/folders
var refs = root && root.ref ? root.ref : [];
if (!Array.isArray(refs)) refs = [refs];

// Timestamp for this inventory run (same for all points processed now)
var nowIso = new Date().toISOString();

// Helpers --------------------------------------------------------------
function parseSystem(name) {
    if (!name) return null;
    var s = String(name);

    if (s.indexOf("$2d") !== -1) {
        return s.split("$2d")[0].trim();
    }
    if (s.indexOf("_") !== -1) {
        return s.split("_")[0].trim();
    }
    return s.trim() || null;
}

function parseComponent(name) {
    if (!name) return null;
    var s = String(name);

    if (s.indexOf("$2d") !== -1) {
        s = s.split("$2d")[1];
    }
    if (s.indexOf("_") !== -1) {
        s = s.split("_")[0];
    }

    s = s.trim();
    return s || null;
}

function inferValueType(typeStr) {
    typeStr = typeStr || "";
    if (/Boolean/i.test(typeStr)) return "bool";
    if (/Numeric|Float|Double|Integer|Number|real/i.test(typeStr)) return "number";
    return "string";
}

/**
 * Create a stable, globally unique ID for a point.
 * Combines integrationType, property, source (controller) and label (/out/ URI).
 */
function makePointUuid(point) {
    var integrationType = point.integrationType || "Obix";
    var property = point.property || "";
    var source = point.source || "";
    var label = point.label || "";

    var base = integrationType + "|" + property + "|" + source + "|" + label;

    var hash = 0, i, chr;
    if (base.length === 0) return "pv_0";
    for (i = 0; i < base.length; i++) {
        chr = base.charCodeAt(i);
        hash = ((hash << 5) - hash) + chr;
        hash |= 0; // Convert to 32-bit int
    }
    return (hash >>> 0).toString(16);
}

// Initialize inventory structure
var inventory = global.get("obixGrossList", 'persistent') || {};
if (!inventory[ip]) inventory[ip] = { systems: {} };
if (!inventory[ip].systems[systemName]) inventory[ip].systems[systemName] = [];

var pointsArray = inventory[ip].systems[systemName];
var pointsForOut = []; // will be sent to next step (GET /out/)

refs.forEach(function (r) {
    if (!r || !r.$) return;
    var a = r.$;

    // Only real points (obix:Point)
    if (!a.is || a.is.indexOf("obix:Point") === -1) return;
    if (!a.href) return;

    var pointName = a.name || a.displayName || a.href.replace(/\/$/, "");

    // baseUri: /obix/config/System/VS3/VS3$2dGT11_mv/
    var relativeHref = a.href.replace(/^\//, "");
    var fullPath = "/obix/config/System/" + systemName + "/" + relativeHref;
    fullPath = fullPath.replace(/\/+$/, "/"); // ensure exactly one trailing slash

    // URI to /out/ – this is what we store in label
    var label = fullPath + "out/";

    var system = parseSystem(pointName) || systemName;
    var component = parseComponent(pointName);
    var valueType = inferValueType(a.is || "");

    // Create or update point object in inventory, match by label
    var existingIndex = pointsArray.findIndex(function (p) { return p && p.label === label; });
    var existingPoint = existingIndex >= 0 ? pointsArray[existingIndex] : null;

    // --- Preserve these two fields from existing point (if any) --------------
    var prevToStream = existingPoint ? existingPoint.toStream : undefined;
    var prevDeprecated = existingPoint ? existingPoint.deprecated : undefined;
    // ------------------------------------------------------------------------

    // Use existing object if it exists, otherwise a new one
    var point = existingPoint || {};

    point.name = a.displayName || pointName;
    point.href = fullPath;
    point.type = valueType;

    // Values are populated later via GET /out/
    if (point.value === undefined) point.value = null;
    if (point.unit === undefined) point.unit = null;

    // Metadata fields
    point.label = label;
    point.property = configProperty;
    point.source = ip;               // source = controller IP
    point.description = pointName;
    point.floor = point.floor || null;
    point.zon = point.zon || null;   // zone (Swedish field name kept for compatibility)
    point.rum = point.rum || null;   // room (Swedish field name kept for compatibility)
    point.system = system;
    point.component = component;
    point.integrationType = "Obix";
    point.systemId = point.property + "_" + system;
    point.componentId = point.systemId + "_" + point.component;

    // NEW: always updated when point is seen in inventory scan
    point.lastSeen = nowIso;

    // Important: make sure we don't keep uri on the point anymore
    if (point.hasOwnProperty("uri")) delete point.uri;
    if (point.hasOwnProperty("rawValue")) delete point.rawValue;
    if (point.hasOwnProperty("ts")) delete point.ts;
    if (point.hasOwnProperty("tsIso")) delete point.tsIso;

    // Stable unique ID for this physical point (based on label)
    if (!point.pointUuid) {
        point.HASH = makePointUuid(point);
    }

    // --- Re-apply preserved values (or defaults if missing) ------------------
    point.toStream = (prevToStream !== undefined) ? prevToStream : "Unknown"; // "Unknown" | true | false
    point.deprecated = (prevDeprecated !== undefined) ? prevDeprecated : false;
    // ------------------------------------------------------------------------

    if (existingIndex >= 0) {
        pointsArray[existingIndex] = point;
    } else {
        pointsArray.push(point);
    }

    pointsForOut.push({
        system: system,
        label: label
    });
});

inventory[ip].systems[systemName] = pointsArray;
global.set("obixGrossList", inventory, 'persistent');

// Send list of points forward for GET /out/
msg.payload = pointsForOut;
msg.points = pointsForOut;

return msg;

/**
 * Build a GET /out/ request for a single OBIX point.
 *
 * Input msg.payload is expected to be:
 *   { system: <systemName>, label: <pointOutUri> }
 */
var config = global.get('config', 'persistent') || global.get('config') || {};
var scheme = config.scheme || "https";
var ip = msg.controllerIp || config.host;

var p = msg.payload; // { system, label }

if (!p || !p.label) {
    node.warn("Missing label on point");
    return null;
}

// Add cookie
var c = flow.get("niagaraCookie");
msg.headers = msg.headers || {};
if (c) {
    msg.headers["Cookie"] = c;
}

msg.method = "GET";
msg.controllerIp = ip;
msg.systemName = p.system;
msg.pointUri = p.label;                 // used by the update function
msg.url = scheme + "://" + ip + p.label; // actual HTTP GET target

return msg;

/**
 * Updates the obixGrossList with live values from a Niagara/OBIX point (/out/ endpoint).
 *
 * For each point:
 *  - Converts string values to the correct JS type (number, boolean, string)
 *  - Extracts engineering units and maps them to a readable symbol
 *  - Writes the result into p.value and p.unit
 *  - Removes legacy fields (rawValue, unitSymbol)
 *
 * Matching logic:
 *  - Uses the point's label (which stores the /out/ URI) instead of a separate uri field.
 *
 * Expected input:
 *  msg.controllerIp  – the Niagara/OBIX host IP (or resolvable name)
 *  msg.payload       – parsed XML→JSON from a GET /out/ operation
 *  msg.pointUri      – the URI of the point being updated (used to match label)
 *
 * Output:
 *  msg.payload       – the updated inventory (for debug)
 */

var config = global.get('config', 'persistent') || global.get('config') || {};
var ip = msg.controllerIp || config.host;
var inv = global.get("obixGrossList",'persistent') || {};
var host = inv[ip];

if (!host || !host.systems) {
    node.warn("No obixGrossList.systems found for IP " + ip);
    return msg;
}

function normalizeUri(u) {
    if (!u) return null;
    u = u.replace(/^https?:\/\/[^/]+/, ""); // remove scheme+host if present
    try { u = decodeURIComponent(u); } catch (e) {}
    if (u && u[0] !== "/") u = "/" + u;
    return u;
}

function unitSymbolFromObixUnit(unit) {
    if (!unit) return null;
    var u = unit.toLowerCase();
    if (u.indexOf("celsius") !== -1) return "°C";
    if (u.indexOf("fahrenheit") !== -1) return "°F";
    if (u.indexOf("percent") !== -1) return "%";
    if (u.indexOf("kelvin") !== -1) return "K";
    return null;
}

/**
 * Update a point by matching on its label (which contains the /out/ URI).
 */
function updatePointByLabel(label, rawValueInput, unitAttr) {
    var target = normalizeUri(label);
    if (!target || !host.systems) return;

    Object.keys(host.systems).forEach(function (sysName) {
        (host.systems[sysName] || []).forEach(function (p) {
            if (!p || !p.label) return;
            var pLabelNorm = normalizeUri(p.label);
            if (pLabelNorm !== target) return;

            // Use both valueType and type hints from OBIX metadata
            var vt = (p.valueType || p.type || "string").toLowerCase();
            var val = rawValueInput;

            if (vt === "number" || vt === "real" || vt === "float" || vt === "double") {
                var n = Number(rawValueInput);
                if (!isNaN(n)) val = n;
            } else if (vt === "bool" || vt === "boolean") {
                val = (String(rawValueInput).toLowerCase() === "true");
            }

            // value = typed value (previously rawValue)
            p.value = val;
            if (p.hasOwnProperty("rawValue")) {
                delete p.rawValue;
            }

            // unit = symbol (previously unitSymbol) or original unitAttr
            if (unitAttr) {
                var sym = unitSymbolFromObixUnit(unitAttr) || unitAttr;
                p.unit = sym;
            }
            if (p.hasOwnProperty("unitSymbol")) {
                delete p.unitSymbol;
            }
        });
    });
}

// --- Extract value and unit from XML→JSON /out/ response ---
var root = msg.payload;

// Some variants: payload.obj.real/bool
if (root && root.obj) root = root.obj;

var a = (root && root.$) ? root.$ : {};

// Normalize the incoming point URI, which should match what you stored in label
var pointLabel = normalizeUri(msg.pointUri || a.href);
var rawValue = null;
var unitAttr = null;

if (a.val !== undefined) rawValue = a.val;
if (a.unit) unitAttr = a.unit;

// Fallback: look for nested <real> or <bool> nodes
if ((rawValue === null || !unitAttr) && root) {
    ["real", "bool"].forEach(function (tag) {
        if (root[tag]) {
            var list = root[tag];
            if (!Array.isArray(list)) list = [list];
            list.forEach(function (r) {
                if (!r || !r.$) return;
                if (r.$.name && r.$.name !== "out") return;
                if (rawValue === null && r.$.val !== undefined) rawValue = r.$.val;
                if (!unitAttr && r.$.unit) unitAttr = r.$.unit;
            });
        }
    });
}

// Call updater with the normalized label, not p.uri
if (pointLabel && rawValue !== null) {
    updatePointByLabel(pointLabel, rawValue, unitAttr);
    inv[ip] = host;
    global.set("obixGrossList", inv,'persistent');
}

// Debug: full inventory for this host
msg.payload = host.systems;
return msg;

/**
 * Initialize login request to OBIX /about/ endpoint using global config.
 *
 * Reads from global config:
 *   host, scheme, port, baseUrl, user, pass
 *
 * Does NOT hardcode any sensitive information in the flow.
 */
var config = global.get('config', 'persistent') || global.get('config') || {};
var host = config.host || "127.0.0.1";
var scheme = config.scheme || "https";
var port = config.port ? (":" + config.port) : "";

msg.method = "POST";
msg.url = scheme + "://" + host  + "/" +  "obix/about/";

// Optional: Basic Auth from config (mocked or real)
if (config.user && config.pass) {
    var token = Buffer.from(config.user + ":" + config.pass).toString("base64");
    msg.headers = msg.headers || {};
    msg.headers["Authorization"] = "Basic " + token;
}

return msg;

/**
 * Save Set-Cookie header(s) from login response into flow context
 * under the key "niagaraCookie".
 */
if (msg.headers && msg.headers["set-cookie"]) {
    var cookies = msg.headers["set-cookie"];
    if (!Array.isArray(cookies)) cookies = [cookies];
    var all = cookies.join("; ");
    flow.set("niagaraCookie", all);
    msg.payload = "Saved cookies: " + all;
} else {
    msg.payload = "No cookie in response.";
}
return msg;
